        // Get the node at the front of the queue
        int node = queue.poll();

        // Check if we have found all the apples
        if (hasApple[node]) {
            return time;
        }

        // Update the distance array
        for (int[] edge : edges) {
            if (node == edge[0]) {
                int neighbor = edge[1];
