    for (int i = 0; i < heights.length; i++) {
        currentHeight = heights[i];

        // Calculate the current area
        currentArea = currentHeight * (i + 1);

        // Update the maximum area
        maxArea = Math.max(maxArea, currentArea);
    }

    // Iterate over the array in reverse
    for (int i = heights.length - 1; i >= 0; i--) {
        currentHeight = heights[i];

        // Calculate the current area
        currentArea = currentHeight * (heights.length - i);

        // Update the maximum area
        maxArea = Math.max(maxArea, currentArea);
    }

    // Return the maximum area
    return maxArea;
}

public static int[] diagonalOrder(int[][] mat) {
    // Initialize an empty array to store the elements in diagonal order
    int[] diagonalOrder = new int[mat.length * mat[0].length];
    // Initialize variables to keep track of the current position in the matrix and the diagonal
    int row = 0, col = 0, diag = 0;
    // Loop through the matrix and fill in the elements in diagonal order
    while (row < mat.length && col < mat[0].length) {
        diagonalOrder[diag] = mat[row][col];
        row++;
        col++;
        diag++;
    }
    // If the matrix is not square, fill in the remaining elements
    if (row < mat.length) {
        for (int i = row; i < mat.length; i++) {
            diagonalOrder[diag] = mat[i][col];
            diag++;
        }
    } else if (col < mat[0].length) {
        for (int i = col; i < mat[0].length; i++) {
            diagonalOrder[diag] = mat[row][i];
            diag++;
        }
    }
    return diagonalOrder;
}

public static int findSmallestInteger(int n) {
    // Check if the input is valid
    if (n <= 0) {
        throw new IllegalArgumentException("Input must be a positive integer");
    }

    // Get the digits of the input number
    String numString = Integer.toString(n);
    char[] digits = numString.toCharArray();

    // Sort the digits in ascending order
    Arrays.sort(digits);

    // Build the smallest rearranged integer
    StringBuilder sb = new StringBuilder();
    for (char c : digits) {
        sb.append(c);
    }
    int rearrangedNum = Integer.parseInt(sb.toString());

    // Check if the rearranged integer is greater than the input number
    if (rearrangedNum > n) {
        return rearrangedNum;
    } else {
        return -1;
    }
}

public static List<String> centerSymmetricNumbers(int n) {
    List<String> centerSymmetricNumbers = new ArrayList<>();

    // Initialize the first and last indices
    int firstIndex = 0;
    int lastIndex = n - 1;

    // Generate the center symmetric numbers
    while (firstIndex <= lastIndex) {
        String centerSymmetricNumber = generateCenterSymmetricNumber(n, firstIndex, lastIndex);
        centerSymmetricNumbers.add(centerSymmetricNumber);

        // Increment the first and last indices
        firstIndex++;
        lastIndex--;
    }

    return centerSymmetricNumbers;
}

public static String generateCenterSymmetricNumber(int n, int firstIndex, int lastIndex) {
    String centerSymmetricNumber = "";

    // Generate the first half of the number
    for (int i = firstIndex; i < n; i++) {
        centerSymmetricNumber += i % 10;
    }

    // Generate the second half of the number
    for (int i = n - 1; i >= lastIndex; i--) {
        centerSymmetricNumber += i % 10;
    }

    return centerSymmetricNumber;
}

public static boolean isBoomerang(int[][] points) {
if (points == null || points.length != 3) {
throw new IllegalArgumentException("Input points must be an array of 3 points.");
}

int[] a = points[0];
int[] b = points[1];
int[] c = points[2];

int dx1 = b[0] - a[0];
int dy1 = b[1] - a[1];
int dx2 = c[0] - b[0];
int dy2 = c[1] - b[1];

int dx3 = a[0] - c[0];
int dy3 = a[1] - c[1];

return dx1 * dy2 == dy1 * dx2 && dx2 * dy3 == dy2 * dx3 && dx3 * dy1 == dy3 * dx1;
}

public static int findNthUglyNumber(int n) {
    int[] factors = new int[] {2, 3, 5};
    int[] uglyNumbers = new int[n];
    uglyNumbers[0] = 1;
    int uglyNumberIndex = 0;
    for (int i = 1; i < n; i++) {
        int minFactor = findMinFactor(factors, uglyNumbers, uglyNumberIndex);
        if (minFactor == -1) {
            return -1;
        }
        uglyNumbers[i] = minFactor * factors[minFactor];
        factors[minFactor]++;
        uglyNumberIndex++;
    }
    return uglyNumbers[n-1];
}

private static int findMinFactor(int[] factors, int[] uglyNumbers, int startIndex) {
    int minFactor = -1;
    int minFactorValue = Integer.MAX_VALUE;
    for (int i = startIndex; i < factors.length; i++) {
        if (uglyNumbers[i] < minFactorValue) {
            minFactor = i;
            minFactorValue = uglyNumbers[i];
        }
    }
    return minFactor;
}

public static int calculateEnergy(String s) {
    int energy = 0;
    int longestNonEmptySubstringLength = 0;
    int currentSubstringLength = 0;
    char previousChar = '\0';
    for (int i = 0; i < s.length(); i++) {
        char currentChar = s.charAt(i);
        if (currentChar == previousChar) {
            currentSubstringLength++;
        } else {
            longestNonEmptySubstringLength = Math.max(longestNonEmptySubstringLength, currentSubstringLength);
            currentSubstringLength = 0;
            previousChar = currentChar;
        }
    }
    energy = s.length() - longestNonEmptySubstringLength;
    return energy;
}

public static List<Integer> lexicalOrder(int n) {
    List<Integer> result = new ArrayList<>();
    for (int i = 1; i <= n; i++) {
        result.add(i);
    }
    result.sort((a, b) -> {
        String aStr = String.valueOf(a);
        String bStr = String.valueOf(b);
        return aStr.compareTo(bStr);
    });
    return result;
}

public static int calculateUniqueSum(int[] nums) {
   // sort the array to ensure that all duplicates are removed
   Arrays.sort(nums);
   // initialize the sum with the first element
   int sum = nums[0];
   // iterate over the rest of the array
   for (int i = 1; i < nums.length; i++) {
       // if the current element is not equal to the previous element
       if (nums[i] != nums[i - 1]) {
           // add the current element to the sum
           sum += nums[i];
       }
   }
   // return the sum
   return sum;
}

public static int minPerfectSquareSum(int n) {
        // Initialize a hash map to store the count of perfect square numbers
        Map<Integer, Integer> count = new HashMap<>();

        // Initialize a variable to store the minimum number of perfect square numbers
        int min = n;

        // Iterate from 1 to n
        for (int i = 1; i <= n; i++) {
            // If the square of the current number is less than or equal to n,
            // increment the count of perfect square numbers
            if (i * i <= n) {
                count.put(i * i, count.getOrDefault(i * i, 0) + 1);
            }
        }

        // Iterate from 1 to n
        for (int i = 1; i <= n; i++) {
            // If the square of the current number is greater than n,
            // break the loop since the minimum number of perfect square numbers
            // is at most the number of perfect square numbers found so far
            if (i * i > n) {
                break;
            }

            // If the count of perfect square numbers is greater than 1,
            // decrement the minimum number of perfect square numbers
            if (count.get(i * i) > 1) {
                min--;
            }
        }

        // Return the minimum number of perfect square numbers
        return min;
    }

public static String reverseWords(String s) {
    // Split the input string into an array of words using " " as the delimiter
    String[] words = s.split(" ");

    // Initialize an empty string builder to store the reversed words
    StringBuilder reversedWords = new StringBuilder();

    // Iterate over each word in the array and reverse the characters
    for (String word : words) {
        // Reverse the word using the StringBuilder API
        StringBuilder reversedWord = new StringBuilder(word).reverse();

        // Add the reversed word to the string builder
        reversedWords.append(reversedWord).append(" ");
    }

    // Return the reversed words as a string
    return reversedWords.toString().trim();
}
